mapper.select:
SELECT B.ID AS BATCH_ID, B.PARK_ID, B.ACTION, B.SOURCE_TYPE, B.SOURCE_ID,
	B.STATUS, B.FAILURE_REASON, B.EXPECTED_COUNT, B.EXPANDED_COUNT, B.ACCEPTED_AT,
	B.EXPANSION_FINISHED_AT, B.UPDATE_TIME AS UPDATED_AT
FROM SMT_AUTH_OPERATION_BATCH B
WHERE B.PARK_ID IN

	#{allowedParkId}


	AND B.PARK_ID = #{filter.parkId}


	AND B.ACTION = #{filter.action}


	AND B.STATUS = #{filter.status}


	AND B.SOURCE_TYPE = #{filter.sourceType}


	AND B.SOURCE_ID = #{filter.sourceId}

ORDER BY B.CREATE_TIME DESC, B.ID DESC

SELECT T.ID AS TARGET_ID, T.REQUEST_ID, T.BATCH_ID, T.PARK_ID,
	T.SUBJECT_TYPE, T.SUBJECT_ID, T.DEVICE_ID, T.RESOURCE_TYPE,
	T.RESOURCE_ID, T.ACTION, T.OPERATION_VERSION, T.STATE, T.FAILURE_REASON,
	T.ACCEPTED_AT, T.DISPATCHED_AT, T.CONFIRMED_AT, T.CONVERGED_AT,
	T.NEXT_ATTEMPT_AT
FROM SMT_AUTH_OPERATION_TARGET T
WHERE T.BATCH_ID = #{filter.batchId}
	AND T.PARK_ID = #{filter.parkId}

	AND T.STATE IN

		#{state}



	AND T.DEVICE_ID = #{filter.deviceId}


	AND T.SUBJECT_TYPE = #{filter.subjectType}

ORDER BY T.CREATE_TIME DESC, T.ID DESC

SELECT TARGET_ID, ATTEMPT_NO, STATUS, EXTERNAL_BATCH_ID, EXTERNAL_COMMAND_ID FROM ( SELECT A.TARGET_ID, A.ATTEMPT_NO, A.STATUS, A.EXTERNAL_BATCH_ID, A.EXTERNAL_COMMAND_ID, ROW_NUMBER() OVER (PARTITION BY A.TARGET_ID ORDER BY A.ATTEMPT_NO DESC, A.ID DESC) AS RN FROM SMT_AUTH_OPERATION_ATTEMPT A WHERE A.TARGET_ID IN
#{targetId}
) WHERE RN = 1 ORDER BY TARGET_ID
